            return False
        i += 6
    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    fib1, fib2 = 0, 1
    count = 0
    while True:
        fib_next = fib1 + fib2
        fib1, fib2 = fib2, fib_next
        if is_prime(fib_next):
            count += 1
            if count == n:
                return fib_next

