def compare_one(a, b):
    """
    编写函数，接收用整数、浮点数或字符串表示的实数，
    并以原来的数据类型返回其中较大的值。
    如果两个值相等，返回 None。
    注意：如果实数以字符串表示，小数点可能是 . 或 ,。
    """
    def convert_to_float(s):
        return float(s.replace(',', '.'))

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        if a == b:
            return None
        return a if a > b else b
    elif isinstance(a, str) and isinstance(b, str):
        a_float = convert_to_float(a)
        b_float = convert_to_float(b)
        if a_float == b_float:
            return None
        return a if a_float > b_float else b
    elif isinstance(a, (int, float)) and isinstance(b, str):
        a_float = a if isinstance(a, float) else float(a)
        b_float = convert_to_float(b)
        if a_float == b_float:
            return None
        return a if a_float > b_float else b
    elif isinstance(a, str) and isinstance(b, (int, float)):
        a_float = convert_to_float(a)
        b_float = b if isinstance(b, float) else float(b)
        if a_float == b_float:
            return None
        return a if a_float > b_float else b
    else:
        raise ValueError("Inputs must be int, float, or str representing a number")

# Test cases
print(compare_one(1, 2.5))  # ➞ 2.5
print(compare_one(1, "2,3"))  # ➞ "2,3"
print(compare_one("5,1", "6"))  # ➞ "6"
print(compare_one("1", 1))  # ➞ None
```

