def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    def find_index(planet):
        try:
            return planets.index(planet)
        except ValueError:
            return -1

    idx1 = find_index(planet1)
    idx2 = find_index(planet2)

    if idx1 == -1 or idx2 == -1 or idx1 == idx2:
        return ()

    if idx1 > idx2:
        idx1, idx2 = idx2, idx1

    return tuple(planets[idx1 + 1:idx2])

# Test cases
