def double_the_difference(lst):
    '''
    给定数字列表，返回列表中奇数的平方和。
    忽略负数以及非整数。
    '''
    def is_positive_odd_integer(n):
        return isinstance(n, int) and n > 0 and n % 2 != 0

    return sum(n**2 for n in lst if is_positive_odd_integer(n))
